BEGIN;
SELECT plan(19);
INSERT INTO auth.users(id,email,email_confirmed_at) VALUES ('f1230000-0000-0000-0000-000000000001','security-admin@test.local',now());
INSERT INTO public.profiles(id,email,account_status) VALUES ('f1230000-0000-0000-0000-000000000001','security-admin@test.local','approved') ON CONFLICT(id) DO UPDATE SET account_status='approved';
INSERT INTO public.user_roles(user_id,role) VALUES ('f1230000-0000-0000-0000-000000000001','admin') ON CONFLICT DO NOTHING;
INSERT INTO public.startup_contracts(id,start_date,status,monthly_fee) VALUES ('f1230000-0000-0000-0000-000000000002',current_date,'draft',150);
INSERT INTO public.startup_contracts(id,start_date,status,monthly_fee,signed_at,signature_status) VALUES ('f1230000-0000-0000-0000-000000000003',current_date,'active',150,now(),'completed');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"f1230000-0000-0000-0000-000000000001","role":"authenticated"}',true);
SELECT throws_ok($$UPDATE public.startup_contracts SET status='active' WHERE id='f1230000-0000-0000-0000-000000000002'$$,'42501',NULL,'unsigned contract cannot activate through API');
SELECT throws_ok($$UPDATE public.startup_contracts SET signed_at=now(),signature_status='signed',status='active' WHERE id='f1230000-0000-0000-0000-000000000002'$$,'42501',NULL,'editor cannot forge signature and activation');
SELECT throws_ok($$UPDATE public.startup_contracts SET monthly_fee=151 WHERE id='f1230000-0000-0000-0000-000000000003'$$,'42501',NULL,'signed fee cannot drift');
SELECT throws_ok($$UPDATE public.startup_contracts SET start_date=current_date+1 WHERE id='f1230000-0000-0000-0000-000000000003'$$,'42501',NULL,'signed dates cannot drift');
SELECT throws_ok($$UPDATE public.startup_contracts SET pricing_snapshot_json='{}' WHERE id='f1230000-0000-0000-0000-000000000003'$$,'42501',NULL,'signed snapshot cannot drift');
SELECT throws_ok($$UPDATE public.startup_contracts SET signed_at=NULL WHERE id='f1230000-0000-0000-0000-000000000003'$$,'42501',NULL,'signature cannot be erased');
SELECT lives_ok($$UPDATE public.startup_contracts SET notes='operational note' WHERE id='f1230000-0000-0000-0000-000000000003'$$,'operational notes remain editable');
SELECT lives_ok($$UPDATE public.startup_contracts SET status='suspended' WHERE id='f1230000-0000-0000-0000-000000000003'$$,'signed contract may be suspended');
SELECT lives_ok($$UPDATE public.startup_contracts SET status='active' WHERE id='f1230000-0000-0000-0000-000000000003'$$,'signed suspended contract may resume');
SELECT lives_ok($$SELECT public.staff_record_manual_contract_signature('f1230000-0000-0000-0000-000000000002')$$,'existing manual staff attestation remains available');
SELECT is((SELECT monthly_fee::int FROM public.startup_contracts WHERE id='f1230000-0000-0000-0000-000000000003'),150,'original agreed fee preserved');
SELECT throws_ok($$UPDATE public.startup_contracts SET activation_sync_pending=false WHERE id='f1230000-0000-0000-0000-000000000002'$$,'42501',NULL,'clients cannot disable activation recovery');
SELECT throws_ok($$SELECT public.staff_renew_contract('f1230000-0000-0000-0000-000000000003',current_date+365,-1)$$,'22023',NULL,'explicit renewal rejects negative fee');
SELECT lives_ok($$SELECT public.staff_renew_contract('f1230000-0000-0000-0000-000000000003',current_date+365,175)$$,'explicit audited renewal remains available');
SELECT is((SELECT monthly_fee::int FROM public.startup_contracts WHERE id='f1230000-0000-0000-0000-000000000003'),175,'explicit renewal changes fee to requested amount');
SELECT is((SELECT pricing_snapshot_json FROM public.startup_contracts WHERE id='f1230000-0000-0000-0000-000000000003'),NULL::jsonb,'renewal does not invent an original pricing snapshot');
RESET ROLE;
UPDATE public.profiles SET account_status='suspended' WHERE id='f1230000-0000-0000-0000-000000000001';
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.staff_record_manual_contract_signature('f1230000-0000-0000-0000-000000000002')$$,'42501',NULL,'suspended admin cannot attest signatures');
SELECT is(public.is_staff(),false,'suspended admin loses staff authorization');
RESET ROLE;
SELECT ok(EXISTS(SELECT 1 FROM cron.job WHERE jobname='reconcile-contract-activation'),'queued signature arms bounded recovery');
SELECT * FROM finish();
ROLLBACK;